static Dictionary<string,object> O(object x){return (Dictionary<string,object>)x;}static double[] N(object x){return ((Array)x).Cast<object>().Select(Convert.ToDouble).ToArray();}static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
static string Hash(string p){using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
static double[] M(IZSceneElement e,bool world=true){var m=world?e.GetTransformToGlobal():e.GetTransformToParent();return Enumerable.Range(0,16).Select(i=>m.GetValue(i/4,i%4)).ToArray();}
static void Set(IZSceneElement e,double[] m,bool pin=true){var v=e.GetTransformToParent();for(int i=0;i<16;i++)v.SetValue(i/4,i%4,m[i]);e.SetTransformToParent(v);if(!pin)return;for(int i=0;i<3;i++){double p=e.get_PositionTransformComponentValue((eZTransformComponentType)i);e.set_PositionTransformComponentExpression((eZTransformComponentType)i,p.ToString("G16",CultureInfo.InvariantCulture)+" m");}}
static double[] Local(double[] m,double[] p){var r=new double[16];r[15]=1;for(int a=0;a<3;a++){for(int b=0;b<3;b++)r[a*4+b]=Enumerable.Range(0,3).Sum(k=>m[a*4+k]*p[b*4+k]);r[12+a]=Enumerable.Range(0,3).Sum(k=>(m[12+k]-p[12+k])*p[a*4+k]);}return r;}
static double[] Turn(double[] m,double[] anchor,double angle,double[] target){var r=(double[])m.Clone();double c=Math.Cos(angle),s=Math.Sin(angle);for(int i=0;i<3;i++){r[i*4]=m[i*4]*c-m[i*4+1]*s;r[i*4+1]=m[i*4]*s+m[i*4+1]*c;}r[12]=target[0]+(m[12]-anchor[0])*c-(m[13]-anchor[1])*s;r[13]=target[1]+(m[12]-anchor[0])*s+(m[13]-anchor[1])*c;r[14]=target[2]+m[14]-anchor[2];return r;}
static IZElement Copy(IZElement e){var m=((IZSceneElement)e).GetTransformToParent();m.MakeIdentity();var items=(Array)((IZSceneElement)e).CreateCopies(1,m);if(items.Length!=1)throw new Exception("One copy expected");return (IZElement)items.GetValue(0);}
static IZFeature Feature(int part,int id){var mgr=(IZPartFeatureMgr)U.GetElementById(part);for(int i=0;i<mgr.GetFeaturesCount();i++)if(((IZElement)mgr.GetFeatureAt(i)).Id==id)return mgr.GetFeatureAt(i);throw new Exception("Missing source cut "+id);}
static List<IZPart> Parts(IZElement e){if(e.Type==eZElementType.Z_ELEMENT_PART)return new List<IZPart>{(IZPart)e};var r=new List<IZPart>();var a=e.GetChildrenZArray();for(int i=0;i<e.GetChildrenCount();i++){object raw;a.Get(i,out raw);r.AddRange(Parts((IZElement)raw));}return r;}
static double Half(IZElement e,int axis){double origin=M((IZSceneElement)e)[12+axis];double maximum=0;foreach(var p in Parts(e)){var b=N(p.GetBody(true).GetBoundingBox());var m=M((IZSceneElement)p);for(int i=0;i<8;i++){var v=new[]{b[(i&1)==0?0:3],b[(i&2)==0?1:4],b[(i&4)==0?2:5]};double x=m[12+axis]+Enumerable.Range(0,3).Sum(k=>v[k]*m[k*4+axis]);maximum=Math.Max(maximum,Math.Abs(x-origin)*1000);}}return maximum;}
