static int Cut(Dictionary<string,object> q,double[] anchor,double angle,double[] target,string label){var original=Feature(Convert.ToInt32(q["source_part"]),Convert.ToInt32(q["source_feature"]));var ex=(IZExtrudeFeature)original;int part=Convert.ToInt32(q["target_part"]);var owner=(IZPart)U.GetElementById(part);var profile=S.CreateProfile();ex.CrossSection.CopyCurvesTo(profile);var f=((IZPartFeatureMgr)owner).CreateExtrudeFeature(eZOperationType.Z_SUBTRACT,false,ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_FORWARD),ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_BACKWARD),0,profile,eZFeatureProfileRelType.Z_FEATURE_PROFILE_ABSORB);Set((IZSceneElement)((IZExtrudeFeature)f).CrossSection,M((IZSceneElement)ex.CrossSection,false),false);((IZExtrudeFeature)f).ExtrudeThroughPart=ex.ExtrudeThroughPart;var world=Turn(M((IZSceneElement)original),anchor,angle,target);Set((IZSceneElement)f,Local(world,M((IZSceneElement)owner)));((IZElement)f).Name="RockPro | Liczba | Wycięcie — "+label;return ((IZElement)f).Id;}
public static int Run(string folder){var report=new Dictionary<string,object>();IZDoc owned=null;bool pass=false;try{
 var q=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)q["contract"]!="rockpro-tv-counts-construct-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong request/host");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var before=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Select(d=>new{path=d.Name,modified=d.Modified}).ToArray();string source=(string)q["source"],output=(string)q["output"];if(Hash(source)!=(string)q["sha256"]||File.Exists(output))throw new Exception("Source changed/output exists");string path=Path.Combine(folder,"working.ics");File.Copy(source,path,false);bool already;owned=app.OpenFile2(path,false,true,out already);if(already){owned=null;throw new Exception("Already open");}S=(IZSceneDoc)owned;U=(IZSceneDocUtility)S;S.ConstraintSolver=false;
 foreach(var p in ((object[])q["parameters"]).Select(O)){if(((string)p["name"]).EndsWith("_Wysokosc"))continue;IZParameter parameter=null;for(int i=0;i<S.ParameterMgr.Count;i++)if(S.ParameterMgr.GetParameter(i).Name==(string)p["name"])parameter=S.ParameterMgr.GetParameter(i);if(parameter==null)parameter=S.ParameterMgr.CreateParameter((bool)p["scalar"]?eZParamType.Z_PARAMETER_TYPE_SCALAR:eZParamType.Z_PARAMETER_TYPE_LENGTH,(string)p["name"],0);parameter.Expression=(string)p["expression"];if(String.IsNullOrEmpty(parameter.Expression))throw new Exception("Invalid parameter "+p["name"]);parameter.Notes=(string)p["notes"];}
 var rows=new List<object>();foreach(var r in ((object[])q["rows"]).Select(O)){File.AppendAllText(Path.Combine(folder,"progress.txt"),DateTime.UtcNow.ToString("o")+" "+r["count"]+Environment.NewLine);var slots=new List<object>();bool handle=(string)r["kind"]=="handle",right=(string)r["side"]=="Prawa";double half=0;
 if(handle){var e=U.GetElementById(Convert.ToInt32(r["source_mount"]));var world=M((IZSceneElement)e);half=Half(e,1);var copies=new List<IZElement>{e};for(int i=1;i<4;i++)copies.Add(Copy(e));for(int i=0;i<4;i++){var ids=new List<int>{copies[i].Id};string label="Uchwyt H7159 — "+r["section"]+" — "+r["side"]+" — pozycja "+(i+1);foreach(var cut in ((object[])r["cuts"]).Select(O))ids.Add(Cut(cut,world.Skip(12).Take(3).ToArray(),0,world.Skip(12).Take(3).ToArray(),label));Set((IZSceneElement)copies[i],Local(world,M((IZSceneElement)copies[i].GetParent())));Name(copies[i],label);slots.Add(ids.ToArray());}var first=O(((object[])r["cuts"])[0]);((IZElement)Feature(Convert.ToInt32(first["source_part"]),Convert.ToInt32(r["remove_feature"]))).Remove();}
 else for(int i=0;i<4;i++){var ids=new List<int>();foreach(var h in ((object[])r["halves"]).Select(O)){var e=U.GetElementById(Convert.ToInt32(h["source_mount"]));var old=M((IZSceneElement)e);var anchor=old.Skip(12).Take(3).ToArray();half=Math.Max(half,Half(e,0));double angle=right?Math.PI/2:-Math.PI/2;var target=new[]{right?(-2032+S.ParameterMgr.GetParameterByName("RP_SzerokoscSkrzyni").Value*1000)/1000:-2.032,(-1011.5+S.ParameterMgr.GetParameterByName((string)r["center"]).Value*1000)/1000,anchor[2]};var fresh=Copy(e);ids.Add(fresh.Id);string label="Zamek L905/915 — "+h["section"]+" — "+r["side"]+" — para "+(i+1);foreach(var cut in ((object[])h["cuts"]).Select(O))ids.Add(Cut(cut,anchor,angle,target,label));Set((IZSceneElement)fresh,Local(Turn(old,anchor,angle,target),M((IZSceneElement)fresh.GetParent())));Name(fresh,label);}slots.Add(ids.ToArray());}
 rows.Add(new{count=r["count"],center=r["center"],spread=r["spread"],minimum=r["minimum"],half_width=half,clearance=12,slots=slots.ToArray()});}
 foreach(var p in ((object[])q["parameters"]).Select(O).Where(p=>((string)p["name"]).EndsWith("_Wysokosc"))){var parameter=S.ParameterMgr.GetParameterByName((string)p["name"]);parameter.Expression=(string)p["expression"];parameter.Notes=(string)p["notes"];}
 var manifest=new{contract="rockpro-tv-counts-v1",rows=rows.ToArray()};S.GetTopElement().get_CustomPropMgr(false).AddCustomProp("RockPro.MountCounts.v1",J.Serialize(manifest),false);S.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);owned.Close2(true);owned=null;
 foreach(var old in before){var d=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(x=>x.Name==old.path);if(d.Modified!=old.modified)throw new Exception("Existing document changed "+old.path);}if(Hash(source)!=(string)q["sha256"])throw new Exception("Original changed");report["output"]=output;report["output_sha256"]=Hash(output);report["source_unchanged"]=true;report["status"]="CONSTRUCTED_NEEDS_MATING_AND_TESTS";pass=true;
}catch(Exception ex){report["error"]=ex.ToString();if(owned!=null)try{owned.Close2(true);}catch{}}report["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));return pass?0:1;}}}
